import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using t-statistics
    t_stats = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for driver selection
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        t, _ = stats.ttest_ind(y0, y1, equal_var=False)
        t_stats.append((abs(t), fid))

    # Sort by absolute t-statistic
    t_stats.sort(reverse=True)

    # Select top features as potential drivers
    drivers = [fid for _, fid in t_stats[:MAX_DRIVERS]]

    # Check for correlated features to avoid near-duplicates
    corr_pairs = []
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            r, _ = stats.pearsonr(feats.x[:, i], feats.x[:, j])
            if abs(r) >= 0.6:
                corr_pairs.append((feats.ids[i], feats.ids[j]))

    # Remove near-duplicates
    used_ids = set()
    filtered_drivers = []
    for fid in drivers:
        if any(fid in pair for pair in corr_pairs):
            # Check if any member of a correlated pair is already selected
            found = False
            for pair in corr_pairs:
                if fid in pair:
                    other = pair[1] if pair[0] == fid else pair[0]
                    if other in used_ids:
                        found = True
                        break
            if not found:
                filtered_drivers.append(fid)
                used_ids.add(fid)
        else:
            filtered_drivers.append(fid)
            used_ids.add(fid)

    # If no strong drivers, return empty design
    if not filtered_drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Simple approach: use top 3 drivers as module members
    module_members = filtered_drivers[:3]

    # Build weighted score from module members
    loadings = {}
    for fid in module_members:
        idx = feats.column(fid)
        # Weight by difference in means between outcome groups
        y0 = feats.x[feats.y == 0, idx]
        y1 = feats.x[feats.y == 1, idx]
        mean_diff = np.mean(y1) - np.mean(y0)
        loadings[fid] = mean_diff

    # Normalize loadings
    total_weight = sum(abs(w) for w in loadings.values())
    if total_weight > 0:
        for fid in loadings:
            loadings[fid] /= total_weight

    # Return design with module members as columns and weighted score
    return Design(
        drivers=tuple(filtered_drivers),
        columns=tuple(module_members),
        products=(),
        loadings=loadings
    )
